import re

from moler.exceptions import ParsingDone, WrongUsage, CommandFailure
from ta_moler.cmd.egen.genericegen import GenericEgen


class Devmem(GenericEgen):
    """Devmem command class."""

    def __init__(self, connection, devmem_path=None, command=None, address=None, value=None, count=None, length=None,
                 mask=None, polling_timeout=None, file=None, dest_address=None, size=None, delay=None, validate=True,
                 prompt=None, newline_chars=None, runner=None):
        """
        Devmem command.

        ./devmem/devmem r {address}
        ./devmem/devmem r {address} {count}
        ./devmem/devmem w {address} {value}
        ./devmem/devmem p {address} {value} {mask} {timeout}
        ./devmem/devmem d {address} {length} {file}
        ./devmem/devmem l {address} {file}
        ./devmem/devmem f {address} {value} {count}
        ./devmem/devmem c {address} {length} {dest_address}
        ./devmem/devmem ww {address} {count} {file} {delay}

        :param connection: moler connection to device, terminal when command is executed.
        :param devmem_path: path to devmem command.
        :param command: Available parameters:
            r: read {count} (one if count not set) 32 bit integers from memory at {address}.
            w: write 32 bit integer to memory at {address}.
            p: poll {value} masked with {mask} at {address} for maximum {timeout} milliseconds.
            d: save (dump) {length} bytes from {address} to {file}.
            l: load memory dump from {file} to memory at {address}.
            f: fill memory starting at {address} with {value} {count} times.
            c: copy {length} bytes from {address} to {dest_address}.
            ww: repeatedly write {count} integers from {file} to memory at {address} with optional {delay}.
        :param address: memory address to act upon.
        :param count: number of 32 bit integers to read (optional in read mode).
        :param length: memory size (in bytes) to save/load memory dump (required in dump mode).
        :param value: value to be written (required in write mode).
        :param mask: mask to use when polling for specific value (if not set 0xFFFFFFFF will be used).
        :param polling_timeout: timeout in milliseconds when polling for specific value (if not set 1 second will be used).
        :param file: file name to save/load memory dump (required in save/load mode).
        :param dest_address: destination address.
        :param size: size of variable (bites).
        :param delay: delay in microseconds (used only in repeated write mode, optional).
        :param validate: validate parameters pass into __init__.
        :param prompt: expected prompt sending by device after command execution.
        :param newline_chars: Characters to split lines.
        :param runner: Runner to run command.
        """
        super(Devmem, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.ret_required = False

        self.devmem_path = devmem_path if devmem_path else "devmem"
        self.command = command
        self.address = address
        self.count = count
        self.length = length
        self.value = value
        self.mask = mask
        self.polling_timeout = polling_timeout
        self.file = file
        self.dest_address = dest_address
        self.size = size
        self.delay = delay
        self.validate = validate
        self._required_params = []

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        if self.validate:
            if self.command:
                cmd = self._build_command_string_with_command_param()
            else:
                cmd = self._build_command_string_without_command_param()
        else:
            # devmem { command } { address } [ value | count | length | mask | timeout ] [ file | dest_address] [delay]
            cmd = self._build_commands_string_without_validation()

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_invalid_number(line)
                self._parse_memory_value(line)
                self._parse_key_value(line)
            except ParsingDone:
                pass
        return super(Devmem, self).on_new_line(line, is_full_line)

    _re_key_value = re.compile(r"(?P<KEY>.*): (?P<VALUE>.*)")

    def _parse_key_value(self, line):
        """
        Parse pair KEY: VALUE from line.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Devmem._re_key_value, line):
            key = self._regex_helper.group("KEY")
            value = self._regex_helper.group("VALUE")

            if value == "FAILED":
                self.set_exception(CommandFailure(self, f"ERROR: Status for '{key}' is '{value}'!"))
            else:
                self.current_ret[key] = value

            raise ParsingDone

    _re_memory_value = re.compile(r"(?P<VALUE>0x[\dABCDEF]+)")

    def _parse_memory_value(self, line):
        """
        Parse memory hexadecimal value in line.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Devmem._re_memory_value, line):
            self.current_ret["VALUE"] = self._regex_helper.group("VALUE")

            raise ParsingDone

    _re_parse_invalid_number = re.compile(r"(?P<ERROR>devmem: invalid number.*)")

    def _parse_invalid_number(self, line):
        """
        Parse invalid number in line.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Devmem._re_parse_invalid_number, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))

            raise ParsingDone

    def _build_commands_string_without_validation(self):
        """
        Build command string without validate __init__ params.

        :return: command string.
        """
        cmd = self.devmem_path

        all_params = [self.command, self.address, self.value, self.count, self.length, self.mask, self.polling_timeout,
                      self.file, self.dest_address, self.delay]

        for param in all_params:
            if param:
                cmd = f"{cmd} {param}"

        return cmd

    def _build_command_string_with_command_param(self):
        """
        Build command string with 'command' param.

        :return: command string.
        """
        self._validate_cmd_params()
        cmd = f"{self.devmem_path} {self.command}"

        for param in self._required_params:
            cmd = f"{cmd} {param}"

        return cmd

    def _build_command_string_without_command_param(self):
        """
        Build command string without 'command' param.

        devmem { command } { address } [ value | count | length | mask | timeout ] [ file | dest_address] [delay]

        This method validates than maximally one of element from logical parameters groups:
         - [ value | count | length | mask | timeout ]
         - [ file | dest_address]
         - [delay]
        have not None value and return string representation of command.

        :return: command string.
        """
        cmd = f"{self.devmem_path} {self.address}"
        first_logical_params_group = [self.value, self.count, self.length, self.mask, self.polling_timeout]
        cmd = self._get_cmd_with_param_from_cmd_params_group(
            cmd=cmd,
            params_group=first_logical_params_group,
        )

        second_logical_params_group = [self.file, self.dest_address]
        cmd = self._get_cmd_with_param_from_cmd_params_group(
            cmd=cmd,
            params_group=second_logical_params_group,
        )

        if self.delay:
            cmd = f"{cmd} {self.delay}"

        return cmd

    def _validate_cmd_params(self):
        """
        Validate that all required parameters was passed into command.

        :return: None.
        """
        if self.command == "r" and not self.count:
            self.count = 1

        required_command_params = {
            "r": [self.address, self.count],
            "w": [self.address, self.value],
            "p": [self.address, self.value, self.mask, self.polling_timeout],
            "d": [self.address, self.length, self.file],
            "l": [self.address, self.file],
            "f": [self.address, self.value, self.count],
            "c": [self.address, self.length, self.dest_address],
            "ww": [self.address, self.count, self.file, self.delay],
        }

        if self.command in required_command_params.keys():
            self._required_params = required_command_params[self.command]

            for param in self._required_params:
                if not param:
                    exception_msg = f"For 'devmem' cmd run with 'command': '{self.command}', got values: '{self._required_params}'."
                    raise WrongUsage(exception_msg)
        else:
            available_commands = ", ".join(required_command_params.keys())
            exception_msg = f"For 'devmem' cmd available 'command' params are: '{available_commands}', but got '{self.command}'."
            raise WrongUsage(exception_msg)

    def _get_cmd_with_param_from_cmd_params_group(self, cmd, params_group):
        """
        Get proper command param to build command string without 'command' parameter.

        :param params_group: group of params.
        :return: proper parameter to build command string.
        """
        if len(params_group) - params_group.count(None) > 1:
            raise WrongUsage(f"Only one from params: '{params_group}' should be pass into command!")

        param = next((param for param in params_group if param is not None), None)
        # Just to get coverage. To fix to more readable form.
        cmd = f"{cmd} {param}" if param else cmd
        return cmd


